	public int findAssetDebtRegisterInfosCount(SqlParam<AssetDebtRegisterInfo> params) throws Exception {
		String sql = "SELECT count(1) FROM app_asset_debt_register_info T1 LEFT JOIN base_report_data_audit_results ARS ON T1.theory_report_start_date = ARS.report_date AND ARS.table_id = 'app_asset_debt_register_info' where T1.sys_data_status ='1' ";
		if (StringUtils.isNotBlank(params.getModel().getRegisterSerno())) {
			sql = sql + " and  T1.register_serno = '" + params.getModel().getRegisterSerno() + "'";
		}if (StringUtils.isNotBlank(params.getModel().getQueryStartDate())) {
			sql = sql + " and  T1.theory_report_start_date  >='"+params.getModel().getQueryStartDate()+"' and T1.theory_report_start_date <='"+params.getModel().getQueryEndDate()+"' ";
		}
		if (StringUtils.isNotBlank(params.getModel().getAssetCode())) {
			sql = sql + " and  T1.asset_code like '%" + params.getModel().getAssetCode() + "%'";
		}
		if (StringUtils.isNotBlank(params.getModel().getAssDebtType())) {
			sql = sql + " and  T1.ass_debt_type = '" + params.getModel().getAssDebtType() + "'";
		}
		if (StringUtils.isNotBlank(params.getModel().getDataChangeType())) {
			sql = sql + " and  T1.data_change_type = '" + params.getModel().getDataChangeType() + "'";
		}
		if (StringUtils.isNotBlank(params.getModel().getRegisterStatus())) {
			sql = sql + " and  T1.register_status = '" + params.getModel().getRegisterStatus() + "'";
		}
		return Integer.parseInt(String.valueOf(super.findRow(Integer.class,sql,DataSourceProperty.PUB, params)));
	}


