	public  List<SqlRow>  findAssDebtTypeDict(Map<String, Object>  params) throws Exception {
		String sql = "SELECT itemkey VALUE,itemval TEXT  FROM sys_dict_item  WHERE dict = 'subm_cbndScdCtg'";
		if(StringUtils.isNotEmpty((String) params.get("assetDebtRegisterType"))){
			switch (Integer.parseInt((String) params.get("assetDebtRegisterType"))){
				case 1:
					sql+=" and itemkey in ('1002','1003','1004','1005') ";
					break;
				case 2:
					sql+=" and itemkey in ('1101','1110','1109','1102','1111','1112','1113','1114','1115','1116','1117','2101','2501','2502') ";
					break;
				case 3:
					sql+=" and itemkey in ('1107','1108','1901','1902') ";
					break;
				case 4:
					sql+=" and itemkey in ('1202','1203','1204','1205','1206','1207','1208','1209','1211','1212','1213','2202') ";
					break;
				case 6:
					sql+=" and itemkey in ('1301','1302','1305') ";
					break;
				case 12:
					sql+=" and itemkey in ('1701','1702','1703','1704','1705','1706') ";
					break;
				case 14:
					sql+=" and itemkey in ('1299','1399','1599','2299') ";
					break;
				case 16:
					sql+=" and itemkey in ('1106','2401','1303','2403','2402','2499','2601','2602','2604','2605','2606','2607','2610','2611','2612','2617','2613','2614','2616','2618','2619','2620','2699') ";
					break;
				default: break;
			}
		}
		sql +=" ORDER BY itemkey+0 ";
		List<SqlRow> s = super.findRows(sql,DataSourceProperty.PUB,params);
		return s;
	}

	/**
	 * 执行交易信息登记更新数据
	 * @param sqlIdList
	 */
	public void executeUpdSql(List<String> sqlIdList, Map<String, Object> params) throws Exception {
		for (String exeId : sqlIdList) {
			super.update(ExeQuery.queryExeId(exeId), DataSourceProperty.PUB, params);
		}
	}


